// Minimal implementation of "Cosmic Dodge" game.
// Canvas with id="game" is assumed to exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth;
  const height = canvas.height = canvas.clientHeight;

  // Game state
  let lastTime = 0;
  let elapsed = 0;
  let running = true;

  // Ship definition (simple triangle)
  const ship = {
    x: 80,
    y: height / 2,
    vy: 0,
    radius: 12,
    thrust: -0.6,
    gravity: 0.02,
    draw() {
      ctx.fillStyle = '#0ff';
      ctx.beginPath();
      ctx.moveTo(this.x, this.y);
      ctx.lineTo(this.x - 15, this.y + 12);
      ctx.lineTo(this.x - 15, this.y - 12);
      ctx.closePath();
      ctx.fill();
    },
    update(dt) {
      this.vy += this.gravity * dt;
      this.y += this.vy * dt;
      // Keep within bounds (top wrap disabled, bottom ends game)
      if (this.y > height) running = false;
    }
  };

  // Input: click / tap thrust upward
  const thrust = () => { ship.vy = ship.thrust; };
  canvas.addEventListener('mousedown', thrust);
  canvas.addEventListener('touchstart', e => { e.preventDefault(); thrust(); });

  // Stars background
  const stars = Array.from({ length: 100 }, () => ({
    x: Math.random() * width,
    y: Math.random() * height,
    r: Math.random() * 2 + 0.5,
    speed: Math.random() * 0.3 + 0.1
  }));
  const updateStars = dt => {
    for (const s of stars) {
      s.x -= s.speed * dt;
      if (s.x < 0) {
        s.x = width;
        s.y = Math.random() * height;
      }
    }
  };
  const drawStars = () => {
    ctx.fillStyle = '#fff';
    for (const s of stars) {
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fill();
    }
  };

  // Asteroids
  const asteroids = [];
  const asteroidSpawnInterval = 2000; // ms
  let nextAsteroid = asteroidSpawnInterval;
  const spawnAsteroid = () => {
    const radius = Math.random() * 20 + 10;
    asteroids.push({
      x: width + radius,
      y: Math.random() * (height - radius * 2) + radius,
      r: radius,
      speed: Math.random() * 0.1 + 0.05
    });
  };
  const updateAsteroids = dt => {
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x -= a.speed * dt;
      if (a.x + a.r < 0) asteroids.splice(i, 1);
    }
  };
  const drawAsteroids = () => {
    ctx.fillStyle = '#a52a2a';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    }
  };

  // Collision detection
  const checkCollision = () => {
    for (const a of asteroids) {
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.r + ship.radius) return true;
    }
    return false;
  };

  // Score display
  const drawScore = () => {
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(elapsed / 1000), 10, 20);
  };

  // Main loop
  const loop = timestamp => {
    if (!lastTime) lastTime = timestamp;
    const dt = (timestamp - lastTime) * 0.06; // speed factor
    lastTime = timestamp;
    if (!running) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#ff0';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', width / 2 - 60, height / 2);
      drawScore();
      return;
    }
    elapsed += dt;

    // Update
    ship.update(dt);
    updateStars(dt);
    updateAsteroids(dt);
    nextAsteroid -= dt;
    if (nextAsteroid <= 0) { spawnAsteroid(); nextAsteroid = asteroidSpawnInterval; }
    if (checkCollision()) running = false;

    // Render
    ctx.clearRect(0, 0, width, height);
    drawStars();
    ship.draw();
    drawAsteroids();
    drawScore();

    requestAnimationFrame(loop);
  };

  requestAnimationFrame(loop);
})();
